CREATE TABLE public.pm_project_b1_cutover_audit (revision bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor uuid NOT NULL,changed_at timestamptz NOT NULL DEFAULT clock_timestamp(),reason text NOT NULL,before_active boolean NOT NULL,after_active boolean NOT NULL,matrix_hash text NOT NULL);
GRANT SELECT ON public.pm_project_b1_cutover_audit TO authenticated;
GRANT ALL ON public.pm_project_b1_cutover_audit TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.pm_project_b1_cutover_audit_revision_seq TO service_role;
REVOKE TRUNCATE ON public.pm_project_b1_cutover_audit FROM anon,authenticated;
ALTER TABLE public.pm_project_b1_cutover_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY b1_audit_admin_read ON public.pm_project_b1_cutover_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TRIGGER b1_audit_immutable BEFORE UPDATE OR DELETE ON public.pm_project_b1_cutover_audit FOR EACH ROW EXECUTE FUNCTION public.pm_cutover_audit_immutable();
CREATE FUNCTION public.pm_project_b1_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT after_active FROM public.pm_project_b1_cutover_audit ORDER BY revision DESC LIMIT 1),false) $$;
CREATE FUNCTION public.pm_project_b1_preview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE m jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; m:=public.pm_project_access_matrix(); RETURN jsonb_build_object('active',public.pm_project_b1_active(),'phase_a_active',public.pm_project_access_cutover_active(),'matrix',m,'matrix_hash',md5((m->'rows')::text)); END $$;
CREATE FUNCTION public.pm_change_project_b1_cutover(_enabled boolean,_expected boolean,_matrix_hash text,_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p jsonb; r bigint; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; IF _enabled IS NULL OR _expected IS NULL OR length(trim(coalesce(_reason,'')))=0 THEN RAISE EXCEPTION 'Explicit cutover state and reason required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('pm.project.b1.cutover',0)); p:=public.pm_project_b1_preview(); IF (p->>'active')::boolean IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'Cutover state changed; reload before saving'; END IF; IF p->>'matrix_hash' IS DISTINCT FROM _matrix_hash THEN RAISE EXCEPTION 'Access matrix changed; review before cutover'; END IF; IF _enabled AND NOT public.pm_project_access_cutover_active() THEN RAISE EXCEPTION 'Phase A must remain active'; END IF; INSERT INTO public.pm_project_b1_cutover_audit(actor,reason,before_active,after_active,matrix_hash) VALUES(auth.uid(),_reason,_expected,_enabled,_matrix_hash) RETURNING revision INTO r; RETURN jsonb_build_object('revision',r,'active',public.pm_project_b1_active()); END $$;
CREATE FUNCTION public.pm_b1_redact(_row jsonb,_project uuid,_kind text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE f boolean; b boolean; e boolean; s boolean; k text; allowed boolean; BEGIN IF NOT public.pm_project_b1_active() THEN RETURN _row; END IF; f:=public.pm_project_area_proposed(_project,'financials',auth.uid()); b:=public.pm_project_area_proposed(_project,'budget_cost',auth.uid()); e:=public.pm_project_area_proposed(_project,'expenses',auth.uid()); s:=public.pm_project_area_proposed(_project,'supplier_fees',auth.uid()); FOR k IN SELECT jsonb_object_keys(_row) LOOP allowed:=true; IF k IN ('sold_fee','sold_internal_fee','sold_pricing_multiplier','sale_rate','hourly_rate','sale_rate_snapshot','amount','retainer_monthly_amount','bill_to_client','billing_model','is_fee_only','invoice_grouping_days','invoice_grouping_enabled') THEN allowed:=f; ELSIF k IN ('sold_external_fee','markup_pct','children_bill_independently') THEN allowed:=f AND s; ELSIF k IN ('cost_rate','cost_rate_snapshot','cost','baseline_budget','baseline_target_hours') THEN allowed:=b; ELSIF k='budget' THEN allowed:=f AND (coalesce((_row->>'is_self')::boolean,true) OR s); ELSIF k IN ('notes','baseline_notes') THEN allowed:=f AND b AND e AND s; END IF; IF NOT allowed THEN _row:=jsonb_set(_row,ARRAY[k],'null'::jsonb); END IF; END LOOP; RETURN _row; END $$;
CREATE FUNCTION public.pm_b1_resource(_resource uuid,_project uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN IF auth.uid() IS NULL OR NOT public.is_psa_staff() THEN RETURN NULL; END IF; IF NOT public.pm_project_b1_active() THEN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_permission(auth.uid(),'finance.dashboard')) THEN RETURN NULL; END IF; SELECT to_jsonb(x) INTO r FROM public.pm_resources x WHERE id=_resource; RETURN r; END IF; IF _project IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.pm_projects p WHERE p.id=_project AND (public.has_role(auth.uid(),'admin') OR public.pm_can_view_projects(auth.uid()) OR public.pm_has_assigned_access(auth.uid(),p.id))) THEN RETURN NULL; END IF; SELECT jsonb_build_object('id',id,'name',name,'full_name',full_name,'role',role,'billing_role',billing_role,'proposal_role',proposal_role,'color',color,'active',active,'team',team,'collaborator_id',collaborator_id,'weekly_capacity',weekly_capacity,'hourly_rate_is_override',hourly_rate_is_override,'created_at',created_at,'updated_at',updated_at,'hourly_rate',hourly_rate,'sale_rate',sale_rate,'cost_rate',cost_rate) INTO r FROM public.pm_resources WHERE id=_resource; RETURN public.pm_b1_redact(r,_project,'resource'); END $$;
CREATE FUNCTION public.pm_b1_projects(_project uuid DEFAULT NULL) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT public.pm_b1_redact(to_jsonb(p),p.id,'project') FROM public.pm_projects p WHERE NOT p.finance_only AND (_project IS NULL OR p.id=_project) ORDER BY p.created_at DESC $$;
CREATE FUNCTION public.pm_b1_stages(_project uuid DEFAULT NULL) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT public.pm_b1_redact(to_jsonb(s),s.project_id,'stage')||jsonb_build_object('allocations',coalesce((SELECT jsonb_agg(to_jsonb(a)||jsonb_build_object('resource',public.pm_b1_resource(a.resource_id,s.project_id),'tasks',coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id)) FROM public.pm_tasks t WHERE t.allocation_id=a.id),'[]'::jsonb))) FROM public.pm_allocations a WHERE a.stage_id=s.id),'[]'::jsonb)) FROM public.pm_stages s WHERE (_project IS NULL OR s.project_id=_project) ORDER BY s.sort_order,s.id $$;
CREATE FUNCTION public.pm_b1_resources(_project uuid DEFAULT NULL) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT public.pm_b1_resource(r.id,_project) FROM public.pm_resources_public r ORDER BY r.name $$;
CREATE FUNCTION public.pm_b1_entries(_project uuid) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT public.pm_b1_redact(to_jsonb(e),_project,'entry') FROM public.pm_time_entries e WHERE e.entry_type='project' AND EXISTS(SELECT 1 FROM public.pm_stages s WHERE s.project_id=_project AND (e.pm_stage_id=s.id OR (s.stage_kind<>'retainer_month' AND e.quote_stage_id=s.source_quote_stage_id) OR EXISTS(SELECT 1 FROM public.pm_tasks t JOIN public.pm_allocations a ON a.id=t.allocation_id WHERE t.id=e.task_id AND a.stage_id=s.id))) $$;
CREATE FUNCTION public.pm_b1_history(_project uuid DEFAULT NULL) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT public.pm_b1_redact(to_jsonb(h),h.project_id,'history') FROM public.historical_time_entries h WHERE _project IS NULL OR h.project_id=_project $$;
REVOKE ALL ON FUNCTION public.pm_project_b1_active(),public.pm_project_b1_preview(),public.pm_change_project_b1_cutover(boolean,boolean,text,text),public.pm_b1_redact(jsonb,uuid,text),public.pm_b1_resource(uuid,uuid),public.pm_b1_projects(uuid),public.pm_b1_stages(uuid),public.pm_b1_resources(uuid),public.pm_b1_entries(uuid),public.pm_b1_history(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_project_b1_active(),public.pm_project_b1_preview(),public.pm_change_project_b1_cutover(boolean,boolean,text,text),public.pm_b1_redact(jsonb,uuid,text),public.pm_b1_resource(uuid,uuid),public.pm_b1_projects(uuid),public.pm_b1_stages(uuid),public.pm_b1_resources(uuid),public.pm_b1_entries(uuid),public.pm_b1_history(uuid) TO authenticated,service_role;
COMMENT ON FUNCTION public.pm_b1_stages(uuid) IS 'B1 operational projection preserves source RLS, never modifies planning/snapshots. Legacy direct readers pending B2/B3 migration.';